import SwiftUI
struct AlertRulesView: View { @EnvironmentObject var model:AppViewModel; var body:some View { VStack(spacing:0) { List { Section("Local rules") { ForEach($model.alertRules) { $rule in HStack { Toggle("",isOn:$rule.enabled).labelsHidden(); VStack(alignment:.leading) { Text(rule.kind.rawValue); Text("\(rule.severity.rawValue) · cooldown \(Int(rule.cooldown/60))m").font(.caption).foregroundStyle(.secondary) }; Spacer(); if model.alertStates[rule.id]?.active == true { Text(model.alertStates[rule.id]?.acknowledgedAt == nil ? "ACTIVE" : "ACKNOWLEDGED").foregroundStyle(.orange); Button("Acknowledge"){model.acknowledge(rule.id)} } } } }; Section("Recent alert events") { ForEach(model.alertEvents.suffix(100).reversed()) { event in HStack { StatusDot(state:event.state); VStack(alignment:.leading) { Text(event.title); Text(event.timestamp.formatted()).font(.caption).foregroundStyle(.secondary) }; Spacer() } } } }; Text("Rules are local and transition-only. Recovery creates a separate event.").font(.caption).foregroundStyle(.secondary).padding() } } }
